function p(s){if(typeof s=="number")return Number.isFinite(s)?s:Number.NaN;const n=String(s??"").trim().replace(/\s/g,"").replace(/[^\d,.\-+]/g,"");if(!n)return Number.NaN;const m=n.startsWith("-")?"-":"",e=n.replace(/^[+-]/,""),r=(e.match(/,/g)||[]).length,a=(e.match(/\./g)||[]).length;let t=e;if(r>0&&a>0)e.lastIndexOf(",")>e.lastIndexOf(".")?t=e.replace(/\./g,"").replace(",","."):t=e.replace(/,/g,"");else if(r>0)if(/^\d{1,3}(,\d{3})+$/.test(e))t=e.replace(/,/g,"");else{const i=e.split(","),d=i.pop()||"";t=`${i.join("")}.${d}`}else a>0&&/^\d{1,3}(\.\d{3})+$/.test(e)&&(t=e.replace(/\./g,""));const o=+`${m}${t}`;return Number.isFinite(o)?o:Number.NaN}export{p};
